export interface MediaConverter {
  mediaConverterId: string;
  ipAddress: string;
  location?: string;

  fx?: boolean;
  tx?: boolean;
  link?: boolean;
  pwr?: boolean;
  act?: boolean;
  fdx?: boolean;
}

export interface SmartMeter {
  id: string;

  smartMeterId: string;
  location?: string;

  latitude?: number;
  longitude?: number;

  status: string;
  addedBy: string;

  createdAt: string;
  updatedAt: string;

  sensors?: any[];
  mediaConverters?: MediaConverter[];
}

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

export async function getAllSmartMeters() {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/smartmeters`,
      {
        credentials: "include",
        cache: "no-store",
      }
    );

    if (!response.ok) {
      throw new Error("Failed to fetch smart meters");
    }

    return await response.json();
  } catch (error) {
    console.error(error);

    return {
      success: false,
      data: [],
    };
  }
}

export async function createSmartMeter(data: any) {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/smartmeters`,
      {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      }
    );
    console.log(response);

    return await response.json();
  } catch (error) {
    console.error(error);

    return {
      success: false,
      error: "Failed to create Smart Meter",
    };
  }
}

// Delete area
export async function deleteSmartMeter(id: string): Promise<ApiResponse<null>> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/smartmeter/${id}`, {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
      },
      credentials: "include",
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || "Failed to delete SmartMeter");
    }

    return await response.json();
  } catch (error) {
    console.error("Error deleting SmartMeter", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Failed to delete SmartMeter",
    };
  }
}
